#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define N 4
#define INF 1000000

typedef struct {
    int x, y;
} Point;

int dist_sq(int x1, int y1, int x2, int y2) {
    int dx = x1 - x2;
    int dy = y1 - y2;
    return dx*dx + dy*dy;
}

int main() {
    char grid[N][N+1];
    Point monsters[16];
    int mcount = 0;

    for (int i = 0; i < N; i++) {
        scanf("%s", grid[i]);
        for (int j = 0; j < N; j++) {
            if (grid[i][j] == 'M') {
                monsters[mcount].x = i;
                monsters[mcount].y = j;
                mcount++;
            }
        }
    }

    int safe[N][N];
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            int min1 = INF, min2 = INF;
            for (int k = 0; k < mcount; k++) {
                int d = dist_sq(i, j, monsters[k].x, monsters[k].y);
                if (d < min1) {
                    min2 = min1;
                    min1 = d;
                } else if (d < min2) {
                    min2 = d;
                }
            }
            safe[i][j] = (min1 == min2);
        }
    }

    // BFS from left column to right column
    int visited[N][N];
    memset(visited, 0, sizeof(visited));
    int queue[64][2];
    int front = 0, rear = 0;

    for (int i = 0; i < N; i++) {
        if (safe[i][0]) {
            visited[i][0] = 1;
            queue[rear][0] = i;
            queue[rear][1] = 0;
            rear++;
        }
    }

    int dx[] = {-1, 1, 0, 0};
    int dy[] = {0, 0, -1, 1};
    int found = 0;

    while (front < rear) {
        int x = queue[front][0];
        int y = queue[front][1];
        front++;

        if (y == N-1) {
            found = 1;
            break;
        }

        for (int d = 0; d < 4; d++) {
            int nx = x + dx[d];
            int ny = y + dy[d];
            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny] && safe[nx][ny]) {
                visited[nx][ny] = 1;
                queue[rear][0] = nx;
                queue[rear][1] = ny;
                rear++;
            }
        }
    }

    if (found)
        printf("possible\n");
    else
        printf("impossible\n");

    return 0;
}

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define SCALE 4
#define N (4*SCALE+1)

char grid[4][5];
int mx[20], my[20], nm;

int on_boundary(int x, int y) {
    // x,y are in scaled coords (0..4*SCALE)
    // actual position is (x/SCALE, y/SCALE)
    // distance squared * SCALE^2 to monster i at (mi*SCALE, mj*SCALE)
    int min_d = -1, cnt = 0;
    for (int i = 0; i < nm; i++) {
        int dx = x - mx[i]*SCALE, dy = y - my[i]*SCALE;
        int d = dx*dx + dy*dy;
        if (min_d < 0 || d < min_d) { min_d = d; cnt = 1; }
        else if (d == min_d) cnt++;
    }
    return cnt >= 2;
}

int dist[N][N];
int dx[] = {1,-1,0,0};
int dy[] = {0,0,1,-1};

int main() {
    for (int i = 0; i < 4; i++) scanf("%s", grid[i]);
    nm = 0;
    for (int i = 0; i < 4; i++)
        for (int j = 0; j < 4; j++)
            if (grid[i][j] == 'M') { my[nm] = i; mx[nm] = j; nm++; }

    memset(dist, -1, sizeof(dist));
    // BFS: enter from left (x=0), exit at right (x=4*SCALE)
    // Or top to bottom? Let's try left to right
    int queue[N*N*2][2]; int head=0,tail=0;
    for (int y = 0; y < N; y++) {
        if (on_boundary(0, y)) { dist[0][y]=0; queue[tail][0]=0; queue[tail][1]=y; tail++; }
    }
    while (head < tail) {
        int cx=queue[head][0], cy=queue[head][1]; head++;
        for (int d=0;d<4;d++) {
            int nx=cx+dx[d], ny=cy+dy[d];
            if (nx<0||nx>=N||ny<0||ny>=N) continue;
            if (dist[nx][ny]>=0) continue;
            if (!on_boundary(nx,ny)) continue;
            dist[nx][ny]=dist[cx][cy]+1;
            queue[tail][0]=nx; queue[tail][1]=ny; tail++;
        }
    }
    int found=-1;
    for (int y=0;y<N;y++) if (dist[N-1][y]>=0 && (found<0||dist[N-1][y]<found)) found=dist[N-1][y];
    if (found<0) printf("impossible\n");
    else printf("%d\n", found);
}

#include <stdio.h>
#include <math.h>

#define EPS 1e-10
#define INF 1e100

typedef struct {
    double x, y;
} Point;

double dist(Point a, Point b) {
    double dx = a.x - b.x;
    double dy = a.y - b.y;
    return sqrt(dx * dx + dy * dy);
}

int main(void) {
    Point m[4];
    for (int i = 0; i < 4; i++) {
        if (scanf("%lf %lf", &m[i].x, &m[i].y) != 2) return 0;
    }

    /* Candidates:
       0..3 : intersections of perpendicular bisectors with x=0
       4..7 : intersections of perpendicular bisectors with x=4
       8    : start side node
       9    : goal side node
    */
    Point p[10];
    int valid[10] = {0};

    int left_id[6], right_id[6];
    int lcnt = 0, rcnt = 0;

    int idx = 0;
    for (int i = 0; i < 4; i++) {
        for (int j = i + 1; j < 4; j++) {
            double xi = m[i].x, yi = m[i].y;
            double xj = m[j].x, yj = m[j].y;

            /* Points equidistant from i and j satisfy:
               2(xj-xi)x + 2(yj-yi)y = xj^2+yj^2 - xi^2-yi^2
            */
            double A = 2.0 * (xj - xi);
            double B = 2.0 * (yj - yi);
            double C = xj * xj + yj * yj - xi * xi - yi * yi;

            if (fabs(B) > EPS) {
                double y0 = (C - A * 0.0) / B;
                if (y0 > EPS && y0 < 4.0 - EPS) {
                    p[idx].x = 0.0;
                    p[idx].y = y0;
                    valid[idx] = 1;
                    left_id[lcnt++] = idx;
                }
                double y4 = (C - A * 4.0) / B;
                if (y4 > EPS && y4 < 4.0 - EPS) {
                    p[idx + 4].x = 4.0;
                    p[idx + 4].y = y4;
                    valid[idx + 4] = 1;
                    right_id[rcnt++] = idx + 4;
                }
            }
            idx++;
        }
    }

    int S = 8, T = 9;
    valid[S] = valid[T] = 1;

    double g[10][10];
    for (int i = 0; i < 10; i++)
        for (int j = 0; j < 10; j++)
            g[i][j] = INF;
    for (int i = 0; i < 10; i++) g[i][i] = 0.0;

    /* Connect left boundary candidates to source, right boundary to sink */
    for (int i = 0; i < lcnt; i++) {
        g[S][left_id[i]] = g[left_id[i]][S] = 0.0;
    }
    for (int i = 0; i < rcnt; i++) {
        g[T][right_id[i]] = g[right_id[i]][T] = 0.0;
    }

    /* Connect candidate points if the segment between them is entirely safe.
       Safe means every point on it has at least two nearest monsters.
       This holds when the segment lies on the common bisector of some pair
       and no other monster is strictly closer at the midpoint. */
    for (int i = 0; i < 8; i++) if (valid[i]) {
        for (int j = i + 1; j < 8; j++) if (valid[j]) {
            Point a = p[i], b = p[j];

            int pair_found = 0;
            for (int u = 0; u < 4 && !pair_found; u++) {
                for (int v = u + 1; v < 4 && !pair_found; v++) {
                    double da1 = dist(a, m[u]), da2 = dist(a, m[v]);
                    double db1 = dist(b, m[u]), db2 = dist(b, m[v]);
                    if (fabs(da1 - da2) < 1e-8 && fabs(db1 - db2) < 1e-8) {
                        /* Check both points lie on bisector of u,v */
                        Point mid;
                        mid.x = (a.x + b.x) * 0.5;
                        mid.y = (a.y + b.y) * 0.5;
                        double d_uv = dist(mid, m[u]);
                        if (fabs(d_uv - dist(mid, m[v])) > 1e-8) continue;

                        int ok = 1;
                        for (int k = 0; k < 4; k++) if (k != u && k != v) {
                            if (dist(mid, m[k]) + 1e-8 < d_uv) {
                                ok = 0;
                                break;
                            }
                        }
                        if (ok) {
                            double w = dist(a, b);
                            g[i][j] = g[j][i] = w;
                            pair_found = 1;
                        }
                    }
                }
            }
        }
    }

    /* Floyd-Warshall */
    for (int k = 0; k < 10; k++)
        for (int i = 0; i < 10; i++)
            for (int j = 0; j < 10; j++)
                if (g[i][k] + g[k][j] < g[i][j])
                    g[i][j] = g[i][k] + g[k][j];

    if (g[S][T] >= INF / 2) {
        printf("impossible\n");
    } else {
        printf("%.10f\n", g[S][T]);
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int INF = 1e9;
int dx[4] = {0, 0, 1, -1};
int dy[4] = {1, -1, 0, 0};

struct State {
    int x, y, mask;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<string> grid(4);
    vector<pair<int,int>> monsters;
    int startX = -1, startY = -1, endX = -1, endY = -1;

    for (int i = 0; i < 4; i++) {
        cin >> grid[i];
        for (int j = 0; j < 4; j++) {
            if (grid[i][j] == 'M') {
                monsters.push_back({i, j});
            } else if (grid[i][j] == 'S') {
                startX = i; startY = j;
            } else if (grid[i][j] == 'G') {
                endX = i; endY = j;
            }
        }
    }

    int m = monsters.size();
    // dist[x][y][mask] = min steps to reach (x,y) with certain monsters "closest" mask
    vector<vector<vector<int>>> dist(4, vector<vector<int>>(4, vector<int>(1<<m, INF)));
    queue<State> q;

    // initial mask: which monsters are equally closest at start
    int startDist = INF;
    for (int i = 0; i < m; i++) {
        int d = abs(startX - monsters[i].first) + abs(startY - monsters[i].second);
        startDist = min(startDist, d);
    }
    int startMask = 0;
    for (int i = 0; i < m; i++) {
        int d = abs(startX - monsters[i].first) + abs(startY - monsters[i].second);
        if (d == startDist) startMask |= (1<<i);
    }

    dist[startX][startY][startMask] = 0;
    q.push({startX, startY, startMask});

    while (!q.empty()) {
        auto [x, y, mask] = q.front(); q.pop();
        int d = dist[x][y][mask];

        if (x == endX && y == endY) {
            cout << d << "\n";
            return 0;
        }

        for (int dir = 0; dir < 4; dir++) {
            int nx = x + dx[dir], ny = y + dy[dir];
            if (nx < 0 || nx >= 4 || ny < 0 || ny >= 4) continue;
            if (grid[nx][ny] == '#') continue;

            // compute closest distance to monsters from new cell
            int minDist = INF;
            for (int i = 0; i < m; i++) {
                int dd = abs(nx - monsters[i].first) + abs(ny - monsters[i].second);
                minDist = min(minDist, dd);
            }
            int newMask = 0;
            int countMin = 0;
            for (int i = 0; i < m; i++) {
                int dd = abs(nx - monsters[i].first) + abs(ny - monsters[i].second);
                if (dd == minDist) {
                    newMask |= (1<<i);
                    countMin++;
                }
            }
            // must have at least 2 equally close monsters to be safe
            if (countMin < 2) continue;

            if (dist[nx][ny][newMask] > d + 1) {
                dist[nx][ny][newMask] = d + 1;
                q.push({nx, ny, newMask});
            }
        }
    }

    cout << "impossible\n";
    return 0;
}

