int main() {
    char grid[4][4];
    vector<pair<int,int>> monsters;

    for (int i = 0; i < 4; i++)
        for (int j = 0; j < 4; j++) {
            cin >> grid[i][j];
            if (grid[i][j] == 'M') monsters.push_back({i, j});
        }

    // For each cell, find min distance and count monsters at that distance
    auto isSafe = [&](int r, int c) -> bool {
        if (monsters.empty()) return true;
        int minDist = INT_MAX;
        int cnt = 0;
        for (auto [mr, mc] : monsters) {
            int d = (r-mr)*(r-mr) + (c-mc)*(c-mc);
            if (d < minDist) { minDist = d; cnt = 1; }
            else if (d == minDist) cnt++;
        }
        return cnt >= 2;
    };

    // BFS from top row to bottom row
    int dist[4][4];
    memset(dist, -1, sizeof(dist));
    queue<pair<int,int>> q;

    for (int j = 0; j < 4; j++) {
        if (isSafe(0, j)) {
            dist[0][j] = 0;
            q.push({0, j});
        }
    }

    int dx[] = {0,0,1,-1};
    int dy[] = {1,-1,0,0};

    while (!q.empty()) {
        auto [r, c] = q.front(); q.pop();
        for (int d = 0; d < 4; d++) {
            int nr = r + dx[d], nc = c + dy[d];
            if (nr < 0 || nr >= 4 || nc < 0 || nc >= 4) continue;
            if (dist[nr][nc] != -1) continue;
            if (!isSafe(nr, nc)) continue;
            dist[nr][nc] = dist[r][c] + 1;
            q.push({nr, nc});
        }
    }

    int ans = INT_MAX;
    for (int j = 0; j < 4; j++)
        if (dist[3][j] != -1) ans = min(ans, dist[3][j]);

    if (ans == INT_MAX) cout << "impossible" << endl;
    else cout << ans + 1 << endl;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

/*
We model the 4x4 area as the square [0,4] x [0,4].
There are 16 monsters, one in each unit cell. Input gives their positions.

Ponta can move only through points where the minimum distance to monsters
is attained by at least two monsters. This is exactly the Voronoi diagram
(boundaries) of the set of monster points, clipped to the square.

So:
- Build all Voronoi edges inside the square.
- These are portions of perpendicular bisectors between pairs of points,
  restricted by half-planes "distance to i <= distance to k" and
  "distance to j <= distance to k" for all k.
- The shortest safe path from left side x=0 to right side x=4 lies on this graph.
- Nodes are Voronoi vertices / intersections with boundary / clipped segment ends.
- Add super source connected to all nodes on x=0, and super sink to all nodes on x=4,
  with edge weight equal to distance along the boundary segment (here 0 since node itself
  lies on boundary; movement happens on Voronoi edges only, so just connect directly).
Actually if a Voronoi edge overlaps boundary, its boundary endpoints are nodes and graph edges
cover movement there. Thus source/sink can connect with zero cost to all boundary nodes.

If any connected component of the safe set touches both left and right boundaries,
Dijkstra on the graph gives the shortest length.

Input format assumed:
16 lines, each with x y (double/int), positions of monsters.
*/

static const double EPS = 1e-9;
static const double INF = 1e100;

struct Point {
    double x, y;
};
Point operator+(Point a, Point b){ return {a.x+b.x,a.y+b.y}; }
Point operator-(Point a, Point b){ return {a.x-b.x,a.y-b.y}; }
Point operator*(Point a, double k){ return {a.x*k,a.y*k}; }

double dot(Point a, Point b){ return a.x*b.x + a.y*b.y; }
double norm(Point a){ return sqrt(dot(a,a)); }
double dist(Point a, Point b){ return norm(a-b); }

struct LineParam {
    Point p, d; // p + t d
};

bool onSquareBoundary(Point p){
    return fabs(p.x) < 1e-8 || fabs(p.x-4.0) < 1e-8 || fabs(p.y) < 1e-8 || fabs(p.y-4.0) < 1e-8;
}

bool insideSquare(Point p){
    return p.x > -1e-8 && p.x < 4.0+1e-8 && p.y > -1e-8 && p.y < 4.0+1e-8;
}

// Clip parameter interval [L,R] on line p+t*d by half-plane A*x + B*y <= C
bool clipHalfPlane(const LineParam& ln, double A, double B, double C, double &L, double &R){
    double num = C - (A*ln.p.x + B*ln.p.y);
    double den = A*ln.d.x + B*ln.d.y;
    if (fabs(den) < EPS){
        if (num < -EPS) return false;
        return true;
    }
    double t = num / den;
    if (den > 0) R = min(R, t);
    else L = max(L, t);
    return L <= R + EPS;
}

string keyPoint(Point p){
    long long X = llround(p.x * 1000000000.0);
    long long Y = llround(p.y * 1000000000.0);
    return to_string(X) + "#" + to_string(Y);
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<Point> m(16);
    for(int i=0;i<16;i++){
        if(!(cin >> m[i].x >> m[i].y)) return 0;
    }

    vector<Point> nodes;
    map<string,int> id;
    auto getId = [&](Point p)->int{
        string k = keyPoint(p);
        auto it = id.find(k);
        if(it != id.end()) return it->second;
        int idx = (int)nodes.size();
        nodes.push_back(p);
        id[k] = idx;
        return idx;
    };

    vector<tuple<int,int,double>> edges;

    // Build Voronoi edges for each pair
    for(int i=0;i<16;i++){
        for(int j=i+1;j<16;j++){
            Point pi = m[i], pj = m[j];
            Point mid = {(pi.x+pj.x)/2.0, (pi.y+pj.y)/2.0};
            Point v = pj - pi;
            if (norm(v) < EPS) continue;
            Point d = {-v.y, v.x}; // perpendicular bisector direction
            LineParam ln{mid, d};

            double L = -1e18, R = 1e18;

            // Inside square constraints
            if(!clipHalfPlane(ln,  1, 0, 4, L, R)) continue; // x <= 4
            if(!clipHalfPlane(ln, -1, 0, 0, L, R)) continue; // x >= 0
            if(!clipHalfPlane(ln, 0,  1, 4, L, R)) continue; // y <= 4
            if(!clipHalfPlane(ln, 0, -1, 0, L, R)) continue; // y >= 0

            // For Voronoi edge: points on bisector where i/j are no farther than any other k
            for(int k=0;k<16;k++){
                if(k==i || k==j) continue;
                Point pk = m[k];
                // |x-pi|^2 <= |x-pk|^2  => 2(pk-pi)·x <= |pk|^2 - |pi|^2
                double A = 2.0*(pk.x - pi.x);
                double B = 2.0*(pk.y - pi.y);
                double C = pk.x*pk.x + pk.y*pk.y - pi.x*pi.x - pi.y*pi.y;
                if(!clipHalfPlane(ln, A, B, C, L, R)) { L=1; R=0; break; }
            }
            if(L > R + EPS) continue;

            Point a = ln.p + ln.d * L;
            Point b = ln.p + ln.d * R;
            if(!insideSquare(a) || !insideSquare(b)) continue;
            if(dist(a,b) < 1e-8) {
                // isolated vertex, still useful if on both boundaries impossible; ignore as no path segment
                continue;
            }

            int u = getId(a), w = getId(b);
            double len = dist(a,b);
            edges.emplace_back(u,w,len);
        }
    }

    int n = nodes.size();
    int S = n, T = n+1;
    vector<vector<pair<int,double>>> g(n+2);

    auto addEdge = [&](int u, int v, double w){
        g[u].push_back({v,w});
        g[v].push_back({u,w});
    };

    for(auto &[u,v,w]: edges) addEdge(u,v,w);

    bool hasLeft = false, hasRight = false;
    for(int i=0;i<n;i++){
        if(fabs(nodes[i].x) < 1e-8){
            addEdge(S, i, 0.0);
            hasLeft = true;
        }
        if(fabs(nodes[i].x - 4.0) < 1e-8){
            addEdge(T, i, 0.0);
            hasRight = true;
        }
    }

    if(!hasLeft || !hasRight){
        cout << "impossible\n";
        return 0;
    }

    vector<double> d(n+2, INF);
    priority_queue<pair<double,int>, vector<pair<double,int>>, greater<pair<double,int>>> pq;
    d[S] = 0;
    pq.push({0,S});

    while(!pq.empty()){
        auto [cd,u] = pq.top(); pq.pop();
        if(cd > d[u] + 1e-12) continue;
        if(u == T) break;
        for(auto [v,w] : g[u]){
            if(d[v] > cd + w + 1e-12){
                d[v] = cd + w;
                pq.push({d[v], v});
            }
        }
    }

    if(d[T] >= INF/2) cout << "impossible\n";
    else{
        cout.setf(ios::fixed);
        cout << setprecision(10) << d[T] << "\n";
    }
    return 0;
}

import java.io.*;
import java.util.*;

public class Main {

    static final int N = 4;
    static int[] mx, my;
    static int sx, sy, tx, ty;

    // Precompute distances from each monster to all cells
    static int[][][] dist;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        // Read monster positions
        mx = new int[4];
        my = new int[4];
        for (int i = 0; i < 4; i++) {
            st = new StringTokenizer(br.readLine());
            mx[i] = Integer.parseInt(st.nextToken());
            my[i] = Integer.parseInt(st.nextToken());
        }

        // Read start and end
        st = new StringTokenizer(br.readLine());
        sx = Integer.parseInt(st.nextToken());
        sy = Integer.parseInt(st.nextToken());
        st = new StringTokenizer(br.readLine());
        tx = Integer.parseInt(st.nextToken());
        ty = Integer.parseInt(st.nextToken());

        // Precompute distances
        dist = new int[4][N][N];
        for (int m = 0; m < 4; m++) {
            for (int i = 0; i < N; i++) {
                Arrays.fill(dist[m][i], Integer.MAX_VALUE);
            }
            // BFS from monster m
            Queue<int[]> q = new LinkedList<>();
            q.add(new int[]{mx[m], my[m]});
            dist[m][mx[m]][my[m]] = 0;
            int[] dx = {1, -1, 0, 0};
            int[] dy = {0, 0, 1, -1};
            while (!q.isEmpty()) {
                int[] cur = q.poll();
                int x = cur[0], y = cur[1];
                for (int d = 0; d < 4; d++) {
                    int nx = x + dx[d];
                    int ny = y + dy[d];
                    if (nx >= 0 && nx < N && ny >= 0 && ny < N && dist[m][nx][ny] == Integer.MAX_VALUE) {
                        dist[m][nx][ny] = dist[m][x][y] + 1;
                        q.add(new int[]{nx, ny});
                    }
                }
            }
        }

        // BFS for shortest path where at each step the cell is "safe"
        // Safe = at least two monsters have equal minimum distance to that cell
        boolean[][] safe = new boolean[N][N];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                int minDist = Integer.MAX_VALUE;
                int count = 0;
                for (int m = 0; m < 4; m++) {
                    if (dist[m][i][j] < minDist) {
                        minDist = dist[m][i][j];
                        count = 1;
                    } else if (dist[m][i][j] == minDist) {
                        count++;
                    }
                }
                safe[i][j] = (count >= 2);
            }
        }

        // BFS from start to target
        Queue<int[]> q = new LinkedList<>();
        boolean[][] visited = new boolean[N][N];
        q.add(new int[]{sx, sy, 0});
        visited[sx][sy] = true;
        int[] dx = {1, -1, 0, 0};
        int[] dy = {0, 0, 1, -1};

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int x = cur[0], y = cur[1], steps = cur[2];
            if (x == tx && y == ty) {
                System.out.println(steps);
                return;
            }
            for (int d = 0; d < 4; d++) {
                int nx = x + dx[d];
                int ny = y + dy[d];
                if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny] && safe[nx][ny]) {
                    visited[nx][ny] = true;
                    q.add(new int[]{nx, ny, steps + 1});
                }
            }
        }

        System.out.println("impossible");
    }
}

