/*
We model the 4x4 area as follows.

Input:
- 4 lines, each containing 4 characters.
- '.' : empty cell
- anything else: monster cell (commonly '#', '*', etc.)

Ponta wants to go from the left side to the right side of the 4x4 square.
He may move through empty cells in 4 directions.
A cell is safe iff the minimum Manhattan distance from that cell to monsters
is attained by at least two monsters (so there is no unique closest monster).

We compute:
1) Positions of all monsters.
2) For each empty cell, whether it is safe.
3) Multi-source BFS from all safe cells in the leftmost column to any safe cell
   in the rightmost column.

If no such path exists, print "impossible".
Otherwise print the minimum number of cells in the path (standard BFS distance
counting starting cell as 0 moves, so output is number of moves).

If there are fewer than 2 monsters total, no cell can satisfy the condition.

This interpretation matches the statement: Ponta can only pass through places
where at least two monsters are equally close to him.
*/

public class Main {
    static final int N = 4;
    static final int[] DR = {-1, 1, 0, 0};
    static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> lines = new ArrayList<>();
        String s;
        while ((s = br.readLine()) != null) {
            s = s.trim();
            if (!s.isEmpty()) lines.add(s);
        }

        if (lines.size() < N) {
            System.out.println("impossible");
            return;
        }

        char[][] g = new char[N][N];
        for (int i = 0; i < N; i++) {
            String row = lines.get(i);
            if (row.length() < N) {
                System.out.println("impossible");
                return;
            }
            for (int j = 0; j < N; j++) g[i][j] = row.charAt(j);
        }

        List<int[]> monsters = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (g[i][j] != '.') monsters.add(new int[]{i, j});
            }
        }

        if (monsters.size() < 2) {
            System.out.println("impossible");
            return;
        }

        boolean[][] safe = new boolean[N][N];
        for (int r = 0; r < N; r++) {
            for (int c = 0; c < N; c++) {
                if (g[r][c] != '.') continue; // can't stand on monster cell
                int best = Integer.MAX_VALUE;
                int cnt = 0;
                for (int[] m : monsters) {
                    int d = Math.abs(r - m[0]) + Math.abs(c - m[1]);
                    if (d < best) {
                        best = d;
                        cnt = 1;
                    } else if (d == best) {
                        cnt++;
                    }
                }
                safe[r][c] = cnt >= 2;
            }
        }

        int[][] dist = new int[N][N];
        for (int i = 0; i < N; i++) Arrays.fill(dist[i], -1);
        ArrayDeque<int[]> q = new ArrayDeque<>();

        for (int r = 0; r < N; r++) {
            if (safe[r][0]) {
                dist[r][0] = 0;
                q.add(new int[]{r, 0});
            }
        }

        int ans = -1;
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1];
            if (c == N - 1) {
                ans = dist[r][c];
                break;
            }
            for (int k = 0; k < 4; k++) {
                int nr = r + DR[k], nc = c + DC[k];
                if (nr < 0 || nr >= N || nc < 0 || nc >= N) continue;
                if (!safe[nr][nc]) continue;
                if (dist[nr][nc] != -1) continue;
                dist[nr][nc] = dist[r][c] + 1;
                q.add(new int[]{nr, nc});
            }
        }

        if (ans == -1) System.out.println("impossible");
        else System.out.println(ans);
    }
}

from heapq import heappop, heappush
from math import inf

def solve():
    import sys
    input = sys.stdin.readline

    # Read the grid
    grid = [list(input().strip()) for _ in range(4)]

    # Locate start (S), goal (G), and monsters (M)
    start = None
    goal = None
    monsters = []
    for i in range(4):
        for j in range(4):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'G':
                goal = (i, j)
            elif grid[i][j] == 'M':
                monsters.append((i, j))

    # Precompute distances to nearest and second nearest monster for each cell
    dist = [[inf] * 4 for _ in range(4)]
    for i in range(4):
        for j in range(4):
            dlist = []
            for mx, my in monsters:
                d = (i - mx) ** 2 + (j - my) ** 2
                dlist.append(d)
            dlist.sort()
            if len(dlist) >= 2:
                # We check if the two smallest distances are equal
                if dlist[0] == dlist[1]:
                    dist[i][j] = 0  # safe cell
                else:
                    dist[i][j] = dlist[0]  # danger level = distance to closest monster
            elif len(dlist) == 1:
                dist[i][j] = dlist[0]
            else:
                dist[i][j] = 0  # no monsters, safe

    # Dijkstra: find path where at every step the cell is safe (dist == 0)
    # We only allow moving to cells where dist == 0
    if dist[start[0]][start[1]] != 0 or dist[goal[0]][goal[1]] != 0:
        print("impossible")
        return

    pq = [(0, start[0], start[1])]
    visited = [[False] * 4 for _ in range(4)]
    dirs = [(-1,0),(1,0),(0,-1),(0,1)]

    while pq:
        steps, x, y = heappop(pq)
        if (x, y) == goal:
            print(steps)
            return
        if visited[x][y]:
            continue
        visited[x][y] = True

        for dx, dy in dirs:
            nx, ny = x + dx, y + dy
            if 0 <= nx < 4 and 0 <= ny < 4 and not visited[nx][ny]:
                if dist[nx][ny] == 0:
                    heappush(pq, (steps + 1, nx, ny))

    print("impossible")

